<script setup lang="ts">import {computed,ref} from 'vue';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import ScoreBadge from '@/components/crm/ScoreBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {showToast} from '@/composables/useToast';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Lead Scoring','Configure future fit and intent score weighting.');function notify(message:string){showToast('Scoring saved',message)}const d=useCrmData();const weights=ref([{label:'Industry fit',value:30,type:'Fit'},{label:'Company size',value:25,type:'Fit'},{label:'Revenue',value:20,type:'Fit'},{label:'Engagement',value:15,type:'Intent'},{label:'Email activity',value:10,type:'Intent'}]);const total=computed(()=>weights.value.reduce((s,x)=>s+x.value,0));</script>
<template><AppShell><PageHeader title="Lead Scoring" description="Prepare fit and intent weighting for the future scoring service"><template #actions><ZButton :disabled="total!==100" @click="notify('Scoring configuration saved in preview mode.')">Save weights</ZButton></template></PageHeader><div class="grid gap-3 xl:grid-cols-[.8fr_1.2fr]"><Panel title="Weighting configuration" description="Weights must total 100%" body-class="p-4"><div v-for="x in weights" :key="x.label" class="mb-5"><div class="flex items-center justify-between text-xs"><span class="font-medium text-content">{{x.label}}</span><span class="num text-content-secondary">{{x.value}}%</span></div><input v-model.number="x.value" class="mt-2 w-full accent-primary" type="range" min="0" max="60" step="5"/><p class="text-2xs text-content-muted">{{x.type}} signal</p></div><div :class="['rounded-md p-3 text-sm font-semibold',total===100?'bg-success/10 text-success':'bg-danger/10 text-danger']">Total weighting: {{total}}%</div></Panel><Panel title="Score preview" description="Illustrative results; calculation remains backend-owned"><div class="divide-y divide-line px-4"><div v-for="lead in (d.leads.data.value??[]).slice(0,8)" :key="lead.id" class="flex items-center justify-between gap-4 py-3"><div><p class="text-sm font-medium text-content">{{lead.name}}</p><p class="text-xs text-content-muted">{{lead.company}} · Fit {{lead.score.fit}} + Intent {{lead.score.intent}}</p></div><ScoreBadge :score="lead.score.total"/></div></div></Panel></div></AppShell></template>
